import numpy as np
from scipy.optimize import minimize

def objective(x):
    r, s = x
    # p = (r - s * (r + 1)) / (r + 1 - s)
    denom = r + 1 - s
    p = (r - s * (r + 1)) / denom
    if p <= 0:
        return 1e9
    return p + r/p + s/r + 1/s

best_val = float('inf')
for r_start in np.linspace(0.1, 10, 20):
    for s_start in np.linspace(0.01, 0.9, 20):
        if s_start < r_start/(r_start+1):
            res = minimize(objective, [r_start, s_start], bounds=[(1e-6, None), (1e-6, None)])
            if res.fun < best_val:
                best_val = res.fun

print(f"Best value: {best_val}")

