import numpy as np
from scipy.optimize import minimize

def objective(x):
    r, s = x
    if s <= 0 or r <= 0:
        return 1e9
    denom = r + 1 - s
    num = r - s * (r + 1)
    if num <= 0 or denom <= 0:
        return 1e9
    p = num / denom
    return p + r/p + s/r + 1/s

best_val = float('inf')
# Search more broadly
for r_start in np.logspace(-2, 2, 10):
    for s_start in np.logspace(-2, 0, 10):
        if s_start < r_start/(r_start+1):
            res = minimize(objective, [r_start, s_start], bounds=[(1e-6, None), (1e-6, None)])
            if res.fun < best_val:
                best_val = res.fun

print(f"Best value: {best_val}")
